def _immutable(name):
    dialect = op.get_bind().dialect.name
    if dialect == "sqlite":
        for action in ("UPDATE", "DELETE"):
            op.execute(
                f"CREATE TRIGGER {name}_no_{action.lower()} BEFORE {action} ON {name} BEGIN SELECT RAISE(ABORT, 'Retained history is immutable'); END"
            )
    elif dialect == "postgresql":
        op.execute(
            f"CREATE OR REPLACE FUNCTION {name}_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Retained history is immutable'; END; $$"
        )
        op.execute(
            f"CREATE TRIGGER {name}_immutable BEFORE UPDATE OR DELETE ON {name} FOR EACH ROW EXECUTE FUNCTION {name}_immutable()"
        )
    elif dialect == "mysql":
        for action in ("UPDATE", "DELETE"):
            op.execute(
                f"CREATE TRIGGER {name}_no_{action.lower()} BEFORE {action} ON {name} FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Retained history is immutable'"
            )


def _freeze_hawalas():
    """Transfers may be edited only until confirmation; no history may be deleted."""
    condition = "EXISTS (SELECT 1 FROM hawala_events WHERE hawala_id = OLD.id AND kind IN ('confirmed','cancelled'))"
    dialect = op.get_bind().dialect.name
    if dialect == "sqlite":
        op.execute(
            f"CREATE TRIGGER hawalas_frozen BEFORE UPDATE ON hawalas WHEN {condition} BEGIN SELECT RAISE(ABORT, 'Transfer is frozen'); END"
        )
        op.execute(
            "CREATE TRIGGER hawalas_retained BEFORE DELETE ON hawalas BEGIN SELECT RAISE(ABORT, 'Transfer is retained'); END"
        )
    elif dialect == "postgresql":
        op.execute(
            f"CREATE OR REPLACE FUNCTION hawalas_frozen() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP = 'DELETE' OR {condition} THEN RAISE EXCEPTION 'Transfer is frozen'; END IF; RETURN NEW; END; $$"
        )
        op.execute(
            "CREATE TRIGGER hawalas_frozen BEFORE UPDATE OR DELETE ON hawalas FOR EACH ROW EXECUTE FUNCTION hawalas_frozen()"
        )
    elif dialect == "mysql":
        op.execute(
            f"CREATE TRIGGER hawalas_frozen BEFORE UPDATE ON hawalas FOR EACH ROW BEGIN IF {condition} THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Transfer is frozen'; END IF; END"
        )
        op.execute(
            "CREATE TRIGGER hawalas_retained BEFORE DELETE ON hawalas FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Transfer is retained'"
        )


def _backfill_agent_openings():
    """Retain existing reviewed agent opening debts as allocatable obligations."""
    bind = op.get_bind()
    target = sa.Table(
        "agent_obligations",
        sa.MetaData(),
        sa.Column("uuid", sa.Uuid()),
        autoload_with=bind,
    )
    rows = (
        bind.execute(
            sa.text("""
        SELECT jl.organization_id, jl.shop_id, ca.contact_id, jl.entry_id,
               jl.account_id, ca.currency_id, ca.direction, jl.amount,
               jl.book_afn, je.created_at
        FROM journal_lines jl
        JOIN journal_entries je ON je.id = jl.entry_id
            AND je.organization_id = jl.organization_id AND je.shop_id = jl.shop_id
        JOIN journal_postings jp ON jp.entry_id = je.id
            AND jp.organization_id = je.organization_id AND jp.shop_id = je.shop_id
        JOIN contact_accounts ca ON ca.account_id = jl.account_id
            AND ca.organization_id = jl.organization_id AND ca.shop_id = jl.shop_id
        WHERE je.action = 'contact:opening' AND ca.role = 'agent'
    """)
        )
        .mappings()
        .all()
    )
    for row in rows:
        created_at = (
            datetime.fromisoformat(row["created_at"])
            if isinstance(row["created_at"], str)
            else row["created_at"]
        )
        bind.execute(
            target.insert().values(
                organization_id=row["organization_id"],
                shop_id=row["shop_id"],
                agent_id=row["contact_id"],
                hawala_id=None,
                kind="opening",
                source_entry_id=row["entry_id"],
                account_id=row["account_id"],
                currency_id=row["currency_id"],
                direction=row["direction"],
                amount=format(abs(Decimal(row["amount"])), "f"),
                book_afn=format(abs(Decimal(row["book_afn"])), "f"),
                uuid=uuid4(),
                created_at=created_at,
                updated_at=created_at,
            )
        )
